diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..6804763
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,84 @@
+// Importing sales from CSV (ticket,soldAt,dishId,qty).
+// Each dish sold consumes one portion of its recipe per qty, with ref
+// "sale:<ticket>". Tickets already imported are skipped; any invalid row or
+// stock shortage rejects the whole file and names the row.
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv, parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+function round3(n) {
+  return Math.round(n * 1000) / 1000;
+}
+
+/** Imports sales; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const [head] = parseCsv(text);
+  if (!head) return { tickets: 0, dishes: 0 };
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+
+  const rows = parseCsvObjects(text);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const soldAt = r.soldAt.endsWith("Z") ? r.soldAt : new Date(r.soldAt).toISOString();
+    const dishId = Number(r.dishId);
+    if (!/^\d+$/.test(r.dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    let dish;
+    try {
+      dish = getDish(store, dishId);
+    } catch {
+      throw new AppError("bad_request", { reason: `${where}: unknown dish ${r.dishId}` });
+    }
+    const recipe = getRecipe(store, dish.recipeId);
+    const qty = Number(r.qty);
+    if (!/^\d+$/.test(r.qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { where, ticket: r.ticket, soldAt, dishId, recipe, qty };
+  });
+
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const remaining = new Map();
+  for (const row of clean) {
+    if (existingTickets.has(row.ticket)) continue;
+    for (const ing of scaled(row.recipe, row.qty)) {
+      if (ing.qty <= 0) continue;
+      if (!remaining.has(ing.itemId)) remaining.set(ing.itemId, round3(onHand(store, ing.itemId)));
+      const available = remaining.get(ing.itemId);
+      if (available < ing.qty) {
+        const item = getItem(store, ing.itemId);
+        throw new AppError("row_not_enough_stock", { where: row.where, item: item.name, available, unit: item.unit });
+      }
+      remaining.set(ing.itemId, round3(available - ing.qty));
+    }
+  }
+
+  store.data.sales ??= [];
+  const importedTickets = new Set();
+  let dishes = 0;
+  for (const row of clean) {
+    if (existingTickets.has(row.ticket)) continue;
+    for (const ing of scaled(row.recipe, row.qty)) {
+      if (ing.qty > 0) consume(store, ing.itemId, ing.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: row.ticket,
+      soldAt: row.soldAt,
+      dishId: row.dishId,
+      qty: row.qty,
+    });
+    importedTickets.add(row.ticket);
+    dishes += row.qty;
+  }
+
+  return { tickets: importedTickets.size, dishes };
+}
